import{c as s,Q as a,j as t,m as p}from"./chunks/framework.DOi4mjdC.js";const i="data:image/png;base64,",e="/assets/3%E7%BB%B4%E6%AD%A3%E5%90%91%E5%8D%B7%E7%A7%AF%E7%A4%BA%E6%84%8F%E5%9B%BE.OZfh6c8y.png",l="/assets/%E5%8D%B7%E7%A7%AF3D%E6%AD%A3%E5%90%91Padding%E7%A4%BA%E6%84%8F%E5%9B%BE.BEtkCemD.png",o="/assets/%E5%8D%B7%E7%A7%AF3D%E6%AD%A3%E5%90%91Stride%E7%A4%BA%E6%84%8F%E5%9B%BE.BXdjxW34.png",c="/assets/%E5%8D%B7%E7%A7%AF3D%E6%AD%A3%E5%90%91Dilation%E7%A4%BA%E6%84%8F%E5%9B%BE.Ba85ucxq.png",m=JSON.parse('{"title":"Conv3D使用说明","description":"","frontmatter":{},"headers":[{"level":1,"title":"Conv3D使用说明","slug":"conv3d使用说明"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件"}],"relativePath":"api/SIMD-API/高阶API/卷积计算/Conv3D/Conv3D-Kernel侧接口/Conv3D使用说明.md","filePath":"api/SIMD-API/高阶API/卷积计算/Conv3D/Conv3D-Kernel侧接口/Conv3D使用说明.md"}'),d={name:"api/SIMD-API/高阶API/卷积计算/Conv3D/Conv3D-Kernel侧接口/Conv3D使用说明.md"};function r(g,n,u,h,C,v){return a(),t("div",null,[...n[0]||(n[0]=[p('<h1 id="conv3d使用说明" tabindex="-1">Conv3D使用说明 <a class="header-anchor" href="#conv3d使用说明" aria-label="Permalink to &quot;Conv3D使用说明&quot;">​</a></h1><p>Ascend C提供一组Conv3D高阶API，方便用户快速实现3维卷积正向矩阵运算。3维正向卷积的示意图如<a href="#fig198021635102613">图1</a>，其计算公式为：</p><p><img src="'+i+'" alt=""></p><ul><li>X为Conv3D卷积的特征矩阵Input。</li><li>W为Conv3D卷积的权重矩阵Weight。</li><li>B为Conv3D卷积的偏置矩阵Bias。</li><li>Y为完成卷积及偏置操作之后的结果矩阵Output。</li></ul><p><strong>图 1</strong> 3维正向卷积示意图<br><img src="'+e+'" alt="" title="3维正向卷积示意图"></p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>Cin为Input的输入通道大小Channel；Din为Input的Depth维度大小；Hin为Input的Height维度大小；Win为Input的Width维度大小；Cout为Weight、Output的输出通道大小；Dout为Output的Depth维度的大小；Hout为Output的Height维度大小；Wout为Output的Width维度大小；下文中提及的M维度，为卷积正向操作过程中的输入Input在img2col展开后的纵轴，数值上等于Hout * Wout。 Channel、Depth、Height、Width后续简称为C、D、H、W。</p></div><p>除上述基础运算外，在Conv3D计算中可以设置参数Padding、Stride和Dilation，具体含义如下。</p><ul><li>Padding代表在输入矩阵的三个维度上填充0，见<a href="#fig16852164019363">图2</a>。</li><li>Stride代表卷积核三个维度上滑动的距离，见<a href="#fig137769564018">图3</a>。</li><li>Dilation代表卷积核三个维度上每个数据的间距，见<a href="#fig1015315044111">图4</a>。</li></ul><p><strong>图 2</strong> 卷积3D正向Padding示意图<br><img src="'+l+'" alt="" title="卷积3D正向Padding示意图"></p><p><strong>图 3</strong> 卷积3D正向Stride示意图<br><img src="'+o+'" alt="" title="卷积3D正向Stride示意图"></p><p><strong>图 4</strong> 卷积3D正向Dilation示意图<br><img src="'+c+`" alt="" title="卷积3D正向Dilation示意图"></p><p>Kernel侧实现Conv3D运算的步骤概括为：</p><ol><li>创建Conv3D对象。</li><li>初始化操作。</li><li>设置3D卷积输入Input、Weight、Bias和输出Output。</li><li>完成3D卷积操作。</li><li>结束3D卷积操作。</li></ol><p>使用Conv3D高阶API实现卷积正向的具体步骤如下：</p><ol><li><p>创建Conv3D对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/conv/conv3d/conv3d_api.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using inputType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::NDC1HWC0, bfloat16_t&gt;;</span></span>
<span class="line"><span>using weightType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::FRACTAL_Z_3D, bfloat16_t&gt;;</span></span>
<span class="line"><span>using outputType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::NDC1HWC0, bfloat16_t&gt;;</span></span>
<span class="line"><span>using biasType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::ND, float&gt;; // 可选参数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Conv3dApi::Conv3D&lt;inputType, weightType, outputType, biasType&gt; conv3dApi;</span></span></code></pre></div><p>创建对象时需要传入Input、Weight和Output参数类型信息；Bias的参数类型为可选参数，不带Bias输入的卷积计算场景，不传入该参数。类型信息通过ConvType来定义，包括：内存逻辑位置、数据格式、数据类型。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;TPosition POSITION, ConvFormat FORMAT, typename TYPE&gt;</span></span>
<span class="line"><span>struct ConvType {</span></span>
<span class="line"><span>    constexpr static TPosition pos = POSITION;    // Conv3d输入或输出在内存上的位置</span></span>
<span class="line"><span>    constexpr static ConvFormat format = FORMAT;  // Conv3d输入或者输出的数据格式</span></span>
<span class="line"><span>    using T = TYPE;                               // Conv3d输入或输出的数据类型</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>下面简要介绍在创建对象时使用到的相关数据结构，开发者可选择性地了解这些内容。用于创建Conv3D对象的数据结构定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class INPUT_TYPE, class WEIGHT_TYPE, class OUTPUT_TYPE, class BIAS_TYPE = biasType, class CONV_CFG = Conv3dParam&gt;</span></span>
<span class="line"><span>using Conv3D = Conv3dIntfExt&lt;Config&lt;ConvApi::ConvDataType&lt;INPUT_TYPE, WEIGHT_TYPE, OUTPUT_TYPE, BIAS_TYPE, CONV_CFG&gt;&gt;, Impl, Intf&gt;</span></span></code></pre></div><p>其中，Conv3dIntfExt和Conv3dParam数据结构定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class Conv3dCfg, template &lt;typename, class, bool&gt; class Impl = Conv3dApiImpl,</span></span>
<span class="line"><span>    template &lt;class, template &lt;typename, class, bool&gt; class&gt; class Intf = Conv3dIntf&gt;</span></span>
<span class="line"><span>struct Conv3dIntfExt : public Intf&lt;Conv3dCfg, Impl&gt; {</span></span>
<span class="line"><span>    __aicore__ inline Conv3dIntfExt()</span></span>
<span class="line"><span>    {}</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>struct Conv3dParam : public ConvApi::ConvParam {</span></span>
<span class="line"><span>    __aicore__ inline Conv3dParam(){};</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>这里的Conv3dIntf是Conv3dIntfExt的基类，Conv3dCfg是Conv3dIntf模板入参，数据结构定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class Config, template &lt;typename, class, bool&gt; class Impl&gt;</span></span>
<span class="line"><span>struct Conv3dIntf {</span></span>
<span class="line"><span>    using InputT = typename Config::SrcAT;</span></span>
<span class="line"><span>    using WeightT = typename Config::SrcBT;</span></span>
<span class="line"><span>    using OutputT = typename Config::DstT;</span></span>
<span class="line"><span>    using BiasT = typename Config::BiasT;</span></span>
<span class="line"><span>    using L0cT = typename Config::L0cT;</span></span>
<span class="line"><span>    using ConvParam = typename Config::ConvParam;</span></span>
<span class="line"><span>    __aicore__ inline Conv3dIntf()</span></span>
<span class="line"><span>    {}</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>template &lt;class ConvDataType&gt;</span></span>
<span class="line"><span>struct Conv3dCfg : public ConvApi::ConvConfig&lt;ConvDataType&gt; {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    __aicore__ inline Conv3dCfg()</span></span>
<span class="line"><span>    {}</span></span>
<span class="line"><span>    using ContextData = struct _ : public ConvApi::ConvConfig&lt;ConvDataType&gt;::ContextData {</span></span>
<span class="line"><span>        __aicore__ inline _()</span></span>
<span class="line"><span>        {}</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><strong>表 1</strong> ConvType说明</p></li></ol><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>TPosition</td><td>内存逻辑位置。 Input矩阵可设置为TPosition::GMWeight矩阵可设置为TPosition::GMBias矩阵可设置为TPosition::GMOutput矩阵可设置为TPosition::GM</td></tr><tr><td>ConvFormat</td><td>数据格式。 Input矩阵可设置为ConvFormat::NDC1HWC0Weight矩阵可设置为ConvFormat::FRACTAL_Z_3DBias矩阵可设置为ConvFormat::NDOutput矩阵可设置为ConvFormat::NDC1HWC0</td></tr><tr><td>TYPE</td><td>数据类型。Input矩阵可设置为half、bfloat16_tWeight矩阵可设置为half、bfloat16_tBias矩阵可设置为half、floatOutput矩阵可设置为half、bfloat16_t 注意：输入输出的矩阵数据类型需要对应，具体支持的数据类型组合关系请参考表2。</td></tr></tbody></table><pre><code>**表 2**  Conv3D输入输出数据类型的组合说明
</code></pre><table tabindex="0"><thead><tr><th>Input矩阵</th><th>Weight矩阵</th><th>Bias</th><th>Output矩阵</th><th>支持平台</th></tr></thead><tbody><tr><td>half</td><td>half</td><td>half</td><td>half</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr><td>bfloat16_t</td><td>bfloat16_t</td><td>float</td><td>bfloat16_t</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr></tbody></table><ol start="2"><li><p>初始化操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Conv3dApi::Conv3D&lt;inputType, weightType, outputType, biasType&gt; conv3dApi;</span></span>
<span class="line"><span>TPipe pipe;                                                        // 初始化TPipe</span></span>
<span class="line"><span>conv3dApi.Init(&amp;tiling);                                           // 初始化conv3dApi</span></span></code></pre></div></li><li><p>设置3D卷积的输入Input、Weight、Bias和输出Output。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>conv3dApi.SetWeight(weightGm);               // 设置当前核的输入weight在gm上的地址</span></span>
<span class="line"><span>if (biasFlag) {</span></span>
<span class="line"><span>    conv3dApi.SetBias(biasGm);               // 设置当前核的输入bias在gm上的地址</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 设置input各个维度在当前核的偏移</span></span>
<span class="line"><span>conv3dApi.SetInputStartPosition(diStartPos, mStartPos);</span></span>
<span class="line"><span>// 设置当前核的cout,dout,m大小</span></span>
<span class="line"><span>conv3dApi.SetSingleOutputShape(singleCoreCout, singleCoreDout, singleCoreM);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 当前Conv3D仅支持单batch的卷积计算，多batch场景通过for循环实现，在循环间计算当前batch的地址偏移</span></span>
<span class="line"><span>for (uint64_t batchIter = 0; batchIter &lt; singleCoreBatch; ++batchIter) {</span></span>
<span class="line"><span>    conv3dApi.SetInput(inputGm[batchIter * inputOneBatchSize]);    // 设置当前核的输入input在gm上的地址</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>完成3D卷积操作。</p><p>调用<a href="./IterateAll-103.html">IterateAll</a>完成单核上所有数据的计算。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (uint64_t batchIter = 0; batchIter &lt; singleCoreBatch; ++batchIter) {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    conv3dApi.IterateAll(outputGm[batchIter * outputOneBatchSize]);    // 调用IterateAll完成Conv3D计算</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>结束3D卷积操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (uint64_t batchIter = 0; batchIter &lt; singleCoreBatch; ++batchIter) {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    conv3dApi.End();    //清除EventID和释放内部申请的临时内存</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ol><h2 id="需要包含的头文件" tabindex="-1">需要包含的头文件 <a class="header-anchor" href="#需要包含的头文件" aria-label="Permalink to &quot;需要包含的头文件&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/conv/conv3d/conv3d_api.h&quot;</span></span></code></pre></div>`,21)])])}const b=s(d,[["render",r]]);export{m as __pageData,b as default};
